export function parseCompendium(): CompendiumItem[] {
  const lines = BLOCO1_CSV.trim().split("\n");
  const items: CompendiumItem[] = [];

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i];
    if (!line || line.startsWith("FIM_DO_BLOCO")) continue;
    
    // Simple CSV parser handling quotes if any
    let parts: string[] = [];
    let cur = "";
    let inQuote = false;
    for (let char of line) {
      if (char === '"') {
        inQuote = !inQuote;
      } else if (char === ',' && !inQuote) {
        parts.push(cur);
        cur = "";
      } else {
        cur += char;
      }
    }
    parts.push(cur);

    if (parts.length >= 13) {
      items.push({
        id: parts[0],
        nome: parts[1],
        categoria: parts[2],
        descricao: parts[3],
        raridade: parts[4],
        peso_kg: Number(parts[5]),
        durabilidade: parts[6],
        stack: Number(parts[7]),
        valor: Number(parts[8]),
        uso_principal: parts[9],
        onde_achar: parts[10],
        interacoes: parts[11],
        receita: parts[12],
      });
    }
  }

  return items;
}
